    "H\u0131zl\u0131 senaryo k\u0131sayolu": "\u0411\u0440\u0437 \u043f\u0440\u0435\u0447\u043d\u0438\u043a \u043d\u0430 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u043e", // EN: Quick scenario shortcut
