    "L\u00fctfen alan\u0131 doldurun.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043f\u043e\u043f\u043e\u043b\u043d\u0435\u0442\u0435 \u0433\u043e \u043f\u043e\u043b\u0435\u0442\u043e.", // EN: Please fill in the field.
    "L\u00fctfen cihaz\u0131n a\u00e7\u0131k ve ayn\u0131 Wi-Fi a\u011f\u0131nda oldu\u011fundan emin olun.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043e\u0441\u0438\u0433\u0443\u0440\u0430\u0458\u0442\u0435 \u0441\u0435 \u0434\u0435\u043a\u0430 \u0443\u0440\u0435\u0434\u043e\u0442 \u0435 \u0432\u043a\u043b\u0443\u0447\u0435\u043d \u0438 \u043f\u043e\u0432\u0440\u0437\u0430\u043d \u043d\u0430 \u0438\u0441\u0442\u0430 Wi-Fi \u043c\u0440\u0435\u0436\u0430.", // EN: Please make sure the device is on and connected to the same Wi-Fi network.
    "L\u00fctfen cihaz\u0131n e\u015fle\u015ftirme modunda oldu\u011fundan emin olun.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043e\u0441\u0438\u0433\u0443\u0440\u0430\u0458\u0442\u0435 \u0441\u0435 \u0434\u0435\u043a\u0430 \u0443\u0440\u0435\u0434\u043e\u0442 \u0435 \u0432\u043e \u0440\u0435\u0436\u0438\u043c \u043d\u0430 \u043f\u043e\u0432\u0440\u0437\u0443\u0432\u0430\u045a\u0435.", // EN: Please make sure the device is in pairing mode.
    "L\u00fctfen cihaz\u0131n\u0131z\u0131n \u00fczerindeki 8 haneli": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u0432\u043d\u0435\u0441\u0435\u0442\u0435 \u0433\u043e 8-\u0446\u0438\u0444\u0440\u0435\u043d\u043e\u0442\u043e", // EN: Please enter the 8-digit
    "L\u00fctfen ge\u00e7erli bir e-posta adresi girin.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u0432\u043d\u0435\u0441\u0435\u0442\u0435 \u0432\u0430\u0436\u0435\u0447\u043a\u0430 \u0435-\u043c\u0430\u0438\u043b \u0430\u0434\u0440\u0435\u0441\u0430.", // EN: Please enter a valid email address.
    "L\u00fctfen ge\u00e7erli bir e-posta girin.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u0432\u043d\u0435\u0441\u0435\u0442\u0435 \u0432\u0430\u0436\u0435\u0447\u043a\u0430 \u0435-\u043c\u0430\u0438\u043b.", // EN: Please enter a valid email.
    "L\u00fctfen ge\u00e7erli bir kod girin.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u0432\u043d\u0435\u0441\u0435\u0442\u0435 \u0432\u0430\u0436\u0435\u0447\u043a\u0430 \u0448\u0438\u0444\u0440\u0430.", // EN: Please enter a valid code.
    "L\u00fctfen t\u00fcm alanlar\u0131 doldurun.": "\u0412\u0435 \u043c\u043e\u043b\u0438\u043c\u0435 \u043f\u043e\u043f\u043e\u043b\u043d\u0435\u0442\u0435 \u0433\u0438 \u0441\u0438\u0442\u0435 \u043f\u043e\u043b\u0438\u045a\u0430.", // EN: Please fill in all fields.
    "MOD: DI\u015eARIDAYIM AKT\u0130F ED\u0130LECEK": "\u0420\u0415\u0416\u0418\u041c: \u041e\u0414\u0421\u0423\u0422\u041d\u041e\u0421\u0422 \u045c\u0435 \u0431\u0438\u0434\u0435 \u0430\u043a\u0442\u0438\u0432\u0438\u0440\u0430\u043d", // EN: MODE: AWAY WILL BE ACTIVATED
    "MUTFAK": "\u041a\u0423\u0408\u041d\u0410", // EN: KITCHEN
    "Maks": "\u041c\u0430\u043a\u0441", // EN: Max
    "Mama Haz\u0131rlay\u0131c\u0131": "\u041f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0443\u0432\u0430\u0447 \u043d\u0430 \u0444\u043e\u0440\u043c\u0443\u043b\u0438", // EN: Formula Maker
    "Manuel": "\u041c\u0430\u043d\u0443\u0435\u043b\u043d\u043e", // EN: Manual
    "Manuel Katalog": "\u041c\u0430\u043d\u0443\u0435\u043b\u0435\u043d \u043a\u0430\u0442\u0430\u043b\u043e\u0433", // EN: Manual Catalog
    "Manuel Kurulum": "\u041c\u0430\u043d\u0443\u0435\u043b\u043d\u043e \u043f\u043e\u0434\u0435\u0441\u0443\u0432\u0430\u045a\u0435", // EN: Manual Setup
    "Manuel Olarak Ekle": "\u0414\u043e\u0434\u0430\u0458 \u0440\u0430\u0447\u043d\u043e", // EN: Add Manually
    "Marka ve \u00fcr\u00fcn listesinden cihaz\u0131n\u0131 se\u00e7erek ekleyebilirsin.": "\u041c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u0433\u043e \u0434\u043e\u0434\u0430\u0434\u0435\u0442\u0435 \u0432\u0430\u0448\u0438\u043e\u0442 \u0443\u0440\u0435\u0434 \u0441\u043e \u0438\u0437\u0431\u043e\u0440 \u043e\u0434 \u043b\u0438\u0441\u0442\u0430\u0442\u0430 \u043d\u0430 \u0431\u0440\u0435\u043d\u0434\u043e\u0432\u0438 \u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438.", // EN: You can add your device by choosing it from the brand and product list.
    "Masa Lambas\u0131": "\u0421\u0432\u0435\u0442\u0438\u043b\u043a\u0430 \u0437\u0430 \u043c\u0430\u0441\u0430", // EN: Desk Lamp
