    "Masa Lambas\u0131 (ZigBee)": "\u0421\u0432\u0435\u0442\u0438\u043b\u043a\u0430 \u0437\u0430 \u043c\u0430\u0441\u0430 (ZigBee)", // EN: Desk Lamp (ZigBee)
    "Masaj Koltu\u011fu": "\u041c\u0430\u0441\u0430\u0436\u0435\u043d \u0441\u0442\u043e\u043b", // EN: Massage Chair
    "Masa\u00fcst\u00fc uygulamas\u0131nda \u00e7al\u0131\u015f\u0131r": "\u0420\u0430\u0431\u043e\u0442\u0438 \u0432\u043e \u0434\u0435\u0441\u043a\u0442\u043e\u043f \u0430\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0458\u0430\u0442\u0430", // EN: Works in the desktop app
    "Matter cihazlar\u0131n\u0131 eklemek i\u00e7in bir Matter denetleyicisi gerekir; NEXUS bu deste\u011fi hen\u00fcz sunmuyor. Cihaz Wi-Fi ile ba\u011flan\u0131yorsa yerel a\u011fdan IP adresiyle ekleyebilirsin.": "\u0414\u043e\u0434\u0430\u0432\u0430\u045a\u0435\u0442\u043e Matter \u0443\u0440\u0435\u0434\u0438 \u0431\u0430\u0440\u0430 Matter \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u0440, \u043a\u043e\u0458 NEXUS \u0441\u00e8 \u0443\u0448\u0442\u0435 \u043d\u0435 \u043d\u0443\u0434\u0438. \u0410\u043a\u043e \u0443\u0440\u0435\u0434\u043e\u0442 \u0441\u0435 \u043f\u043e\u0432\u0440\u0437\u0443\u0432\u0430 \u043f\u0440\u0435\u043a\u0443 Wi-Fi, \u043c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u0433\u043e \u0434\u043e\u0434\u0430\u0434\u0435\u0442\u0435 \u043e\u0434 \u0432\u0430\u0448\u0430\u0442\u0430 \u043b\u043e\u043a\u0430\u043b\u043d\u0430 \u043c\u0440\u0435\u0436\u0430 \u043f\u0440\u0435\u043a\u0443 \u043d\u0435\u0433\u043e\u0432\u0430\u0442\u0430 IP \u0430\u0434\u0440\u0435\u0441\u0430.", // EN: Adding Matter devices needs a Matter controller, which NEXUS doesn't offer yet. If the device connects over Wi-Fi, you can add it from your local network by its IP address.
    "Matter kurulum kodu": "Matter \u043a\u043e\u0434 \u0437\u0430 \u043f\u043e\u0434\u0435\u0441\u0443\u0432\u0430\u045a\u0435", // EN: Matter setup code
    "Mavi": "\u0421\u0438\u043d\u0430", // EN: Blue
    "Medya Aktar\u0131m\u0131": "\u041f\u0440\u0435\u043d\u043e\u0441 \u043d\u0430 \u043c\u0435\u0434\u0438\u0443\u043c\u0438", // EN: Media Handoff
    "Medya odakl\u0131 e\u011flence profilini tetikle.": "\u0410\u043a\u0442\u0438\u0432\u0438\u0440\u0430\u0458\u0442\u0435 \u0433\u043e \u043c\u0435\u0434\u0438\u0458\u0441\u043a\u0438 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0430\u043d\u0438\u043e\u0442 \u043f\u0440\u043e\u0444\u0438\u043b \u0437\u0430 \u0437\u0430\u0431\u0430\u0432\u0430.", // EN: Trigger the media-focused entertainment profile.
    "Medya panelinden a\u00e7\u0131l\u0131r": "\u0421\u0435 \u0432\u043a\u043b\u0443\u0447\u0443\u0432\u0430 \u043e\u0434 \u043c\u0435\u0434\u0438\u0458\u0430 \u043f\u0430\u043d\u0435\u043b\u043e\u0442", // EN: Turns on from the media panel
    "Medya ve Ses": "\u041c\u0435\u0434\u0438\u0443\u043c\u0438 \u0438 \u0410\u0443\u0434\u0438\u043e", // EN: Media and Audio
    "Medya ve e\u011flence": "\u041c\u0435\u0434\u0438\u0443\u043c\u0438 \u0438 \u0437\u0430\u0431\u0430\u0432\u0430", // EN: Media and entertainment
    "Medya ve e\u011flence paneli": "\u041f\u0430\u043d\u0435\u043b \u0437\u0430 \u043c\u0435\u0434\u0438\u0443\u043c\u0438 \u0438 \u0437\u0430\u0431\u0430\u0432\u0430", // EN: Media and entertainment panel
    "Medya ve ortam cihazlar\u0131yla kar\u015f\u0131lama sahnesi \u00e7al\u0131\u015ft\u0131r.": "\u041f\u043e\u043a\u0440\u0435\u043d\u0438 \u0441\u0446\u0435\u043d\u0430 \u0437\u0430 \u0434\u043e\u0431\u0440\u0435\u0434\u043e\u0458\u0434\u0435 \u0441\u043e \u043c\u0435\u0434\u0438\u0443\u043c\u0441\u043a\u0438 \u0438 \u0430\u043c\u0431\u0438\u0435\u043d\u0442\u0430\u043b\u043d\u0438 \u0443\u0440\u0435\u0434\u0438.", // EN: Run a welcome scene with media and ambient devices.
    "Menzil Artt\u0131r\u0131c\u0131": "\u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0443\u0432\u0430\u0447 \u043d\u0430 \u043e\u043f\u0441\u0435\u0433", // EN: Range Extender
    "Men\u00fc": "\u041c\u0435\u043d\u0438", // EN: Menu
    "Mesaj Merkezi": "\u0426\u0435\u043d\u0442\u0430\u0440 \u0437\u0430 \u043f\u043e\u0440\u0430\u043a\u0438", // EN: Message Center
    "Mesaj\u0131 g\u00f6nder": "\u0418\u0441\u043f\u0440\u0430\u0442\u0438 \u043f\u043e\u0440\u0430\u043a\u0430", // EN: Send message
    "Mesaj\u0131n": "\u0422\u0432\u043e\u0458\u0430\u0442\u0430 \u043f\u043e\u0440\u0430\u043a\u0430", // EN: Your message
    "Meteoroloji Saati": "\u0412\u0440\u0435\u043c\u0435\u043d\u0441\u043a\u0438 \u0447\u0430\u0441\u043e\u0432\u043d\u0438\u043a", // EN: Weather Clock
    "Mevcut cihazlar\u0131n\u0131za g\u00f6re size \u00f6zel senaryo \u00f6nerileri.": "\u041f\u0440\u0435\u0434\u043b\u043e\u0437\u0438 \u0437\u0430 \u0441\u0446\u0435\u043d\u0430\u0440\u0438\u0458\u0430 \u043f\u0440\u0438\u043b\u0430\u0433\u043e\u0434\u0435\u043d\u0438 \u043d\u0430 \u0442\u0432\u043e\u0438\u0442\u0435 \u0442\u0435\u043a\u043e\u0432\u043d\u0438 \u0443\u0440\u0435\u0434\u0438.", // EN: Scenario suggestions tailored to your current devices.
    "Mevcut \u015fifre": "\u0422\u0435\u043a\u043e\u0432\u043d\u0430 \u043b\u043e\u0437\u0438\u043d\u043a\u0430", // EN: Current password
    "Mevcut \u015fifre e\u015fle\u015fmiyor.": "\u0422\u0435\u043a\u043e\u0432\u043d\u0430\u0442\u0430 \u043b\u043e\u0437\u0438\u043d\u043a\u0430 \u043d\u0435 \u0441\u0435 \u0441\u043e\u0432\u043f\u0430\u0453\u0430.", // EN: Current password doesn't match.
    "Mevsimlik Neutron \u00dcr\u00fcnler": "\u0421\u0435\u0437\u043e\u043d\u0441\u043a\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438", // EN: Seasonal Products
    "Meyve Kurutma Makinesi": "\u0414\u0435\u0445\u0438\u0434\u0440\u0430\u0442\u043e\u0440 \u0437\u0430 \u043e\u0432\u043e\u0448\u0458\u0435", // EN: Fruit Dehydrator
    "Meyve S\u0131kaca\u011f\u0131": "\u0421\u043e\u043a\u043e\u0432\u043d\u0438\u043a", // EN: Juicer
    "Mikrodalga F\u0131r\u0131n": "\u041c\u0438\u043a\u0440\u043e\u0431\u0440\u0430\u043d\u043e\u0432\u0430 \u043f\u0435\u0447\u043a\u0430", // EN: Microwave Oven
    "Mini uygulama men\u00fcs\u00fc": "\u041c\u0435\u043d\u0438 \u0437\u0430 \u043c\u0438\u043d\u0438 \u0430\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u0458\u0430", // EN: Mini app menu
