    "NEXUS Ailesine Kat\u0131l\u0131n": "\u041f\u0440\u0438\u0434\u0440\u0443\u0436\u0435\u0442\u0435 \u0441\u0435 \u043d\u0430 NEXUS \u0441\u0435\u043c\u0435\u0458\u0441\u0442\u0432\u043e\u0442\u043e", // EN: Join the NEXUS Family
