    "Routerlar": "\u0420\u0443\u0442\u0435\u0440\u0438", // EN: Routers
    "Rutin ayarla": "\u041f\u043e\u0441\u0442\u0430\u0432\u0438 \u0440\u0443\u0442\u0438\u043d\u0430", // EN: Set up routine
    "Rutinden \u00d6nce Kontrol": "\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u0440\u0435\u0434 \u0440\u0443\u0442\u0438\u043d\u0430\u0442\u0430", // EN: Check Before Routine
