    "SMS ile s\u0131f\u0131rla": "\u0420\u0435\u0441\u0435\u0442\u0438\u0440\u0430\u0458 \u043f\u0440\u0435\u043a\u0443 \u0421\u041c\u0421", // EN: Reset by SMS
    "SMS ve \u00c7a\u011fr\u0131 Bildirimleri": "\u0418\u0437\u0432\u0435\u0441\u0442\u0443\u0432\u0430\u045a\u0430 \u043f\u0440\u0435\u043a\u0443 \u0421\u041c\u0421 \u0438 \u043f\u043e\u0432\u0438\u043a", // EN: SMS and Call Notifications
    "SSS & Geribildirim": "\u0427\u041f\u041f & \u041f\u043e\u0432\u0440\u0430\u0442\u043d\u0438 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438", // EN: FAQ & Feedback
